DO $$ DECLARE fn text; def text; old text; BEGIN FOREACH fn IN ARRAY ARRAY['public.online_shift_remaining(uuid,date,text)','public.online_slot_remaining(uuid,date,text,text,uuid)'] LOOP SELECT pg_get_functiondef(fn::regprocedure) INTO def; old:='doubled:=doubled OR public.restaurant_web_double_day(_rid,_date);'; IF position(old IN def)=0 THEN RAISE EXCEPTION 'Contratto capienza turni cambiato'; END IF; def:=replace(def,old,'IF (SELECT online_turns_override FROM public.restaurants WHERE id=_rid) THEN doubled:=public.restaurant_web_double_day(_rid,_date); END IF;'); EXECUTE def; END LOOP; END $$;